-- composition of rule kernels P:CombinePartialFinalAggregate x P:EnsureRequirements (datafusion), template exists
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT ' '::text AS c0, 3 AS c1 ORDER BY 1) AS ka WHERE EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT MIN (CASE WHEN (SELECT BOOL_AND (FALSE) FROM tp AS a2) THEN a1.c0 ELSE a1.c0 END) AS c0, 5e-324::float8 AS c1 FROM t0 AS a1 GROUP BY CUBE (a1.c0)) AS kb);
